"""Select received sales history and browse its source-linked lines."""
HTML='''<section class="card files-section"><h2>USAR VENTAS HISTÓRICAS RECIBIDAS</h2><p id="selected-sales-company"></p><p id="selected-sales-current"></p><details><summary>Seleccionar archivos y revisar las últimas ventas</summary><p>Recibe primero tu Excel o CSV como Líneas de facturas de venta. En Expedientes recibidos, marca solo los archivos de ventas de esta empresa ficticia y corte. Usa códigos exactos de cliente y SKU del catálogo activo.</p><button id="selected-sales-preview" type="button">Comprobar las ventas marcadas</button><div id="selected-sales-review" class="files-step" hidden><h3>LÍNEAS PROPUESTAS · SIN UTILIZAR TODAVÍA</h3><p id="selected-sales-summary"></p><div id="selected-sales-rows" class="scroll"></div><p>La selección sustituye la selección recibida anterior completa y se consulta junto a los documentos originales. Incluye todas las partes que quieras mantener. Las facturas ya presentes en los documentos originales y las líneas repetidas se bloquean. No se crean facturas fiscales, movimientos de stock, cobros ni vencimientos.</p><p>El precio efectivo es el neto de la línea dividido por su cantidad. Las referencias para negociar utilizan el cliente seleccionado, el mismo SKU, la misma unidad y EUR. Si hay varias líneas en la última fecha, no se elige una arbitrariamente. El historial queda separado de las facturas originales y de la conciliación de vencimientos.</p></div><div class="fields"><label>Responsable<input id="selected-sales-actor" maxlength="500"></label><label>Motivo<input id="selected-sales-reason" maxlength="500"></label></div><label><input id="selected-sales-ack" type="checkbox" style="display:inline;width:auto"> He revisado las líneas, sus referencias y su fecha. Se utilizarán como historial recibido al corte, sin acreditar cobro ni salida de almacén.</label><div class="files-actions"><button id="selected-sales-commit" type="button" class="primary" disabled>Usar este historial en las propuestas</button><button id="selected-sales-clear" type="button" disabled>Retirar el historial recibido seleccionado</button></div></details><p id="selected-sales-notice" class="files-notice" role="status"></p></section>'''
SALES_HTML='''<section class="card"><h2>VENTAS · LÍNEAS RECIBIDAS SELECCIONADAS</h2><p id="received-sales-scope"></p><label>Buscar factura, cliente, SKU o archivo<input id="received-sales-query" type="search"></label><p id="received-sales-count" role="status"></p><div id="received-sales-lines" class="scroll"></div><div class="files-actions"><button id="received-sales-prev" type="button">Anterior</button><button id="received-sales-next" type="button">Siguiente</button></div></section>'''
JS=r'''
let selectedSalesTicket=null,selectedSalesSequence=0,selectedSalesBusy=false,receivedSalesPage=0;
function invalidateSelectedSales(){selectedSalesSequence++;selectedSalesTicket=null;$('selected-sales-ack').checked=false;$('selected-sales-review').hidden=true;$('selected-sales-commit').disabled=true}
function salesReceivedTable(target,lines){receptionTable(target,['Factura / fecha','Cliente','SKU','Cantidad / unidad','Neto de línea','Precio neto / unidad','Archivo / fila'],lines.map(l=>[l.invoice_number+' · '+stockDate(l.issue_date),l.customer_name+' / '+l.customer_id,l.article_id,stockNumber(l.quantity)+' '+l.unit,money(l.net_amount)+' EUR',money(l.effective_net_unit_price)+' EUR',l.source_refs.map(s=>s.filename+' · fila '+s.row).join(' · ')]))}
function renderSelectedSales(){invalidateSelectedSales();const s=state.selected_sales_history;$('selected-sales-company').textContent='Empresa activa: '+(state.info.company.legal_name||state.info.company.company_id)+' · corte '+stockDate(state.info.as_of_date);$('selected-sales-current').textContent=s?s.message:'Sin líneas recibidas seleccionadas; se conserva el historial documental original.';$('selected-sales-clear').disabled=!s||s.status==='CLEARED';$('received-sales-scope').textContent=s?s.message:'Recibe y selecciona líneas de venta desde Carga de archivos para consultarlas aquí.';receivedSalesPage=0;$('received-sales-query').value='';filterReceivedSales()}
function filterReceivedSales(){const query=$('received-sales-query').value.trim().toLocaleLowerCase('es'),rows=(state.received_sales_lines||[]).filter(l=>!query||[l.invoice_number,l.customer_name,l.customer_id,l.article_id,...l.source_refs.map(s=>s.filename)].join(' ').toLocaleLowerCase('es').includes(query));receivedSalesPage=Math.max(0,Math.min(receivedSalesPage,Math.ceil(rows.length/100)-1));const page=rows.slice(receivedSalesPage*100,(receivedSalesPage+1)*100);salesReceivedTable('received-sales-lines',page);$('received-sales-count').textContent='Mostrando '+page.length+' de '+rows.length+' líneas · página '+(receivedSalesPage+1)+' de '+Math.max(1,Math.ceil(rows.length/100));$('received-sales-prev').disabled=receivedSalesPage===0;$('received-sales-next').disabled=(receivedSalesPage+1)*100>=rows.length}
$('received-sales-query').addEventListener('input',()=>{receivedSalesPage=0;filterReceivedSales()});$('received-sales-prev').onclick=()=>{receivedSalesPage--;filterReceivedSales()};$('received-sales-next').onclick=()=>{receivedSalesPage++;filterReceivedSales()};
$('selected-sales-ack').onchange=()=>{$('selected-sales-commit').disabled=!selectedSalesTicket||!$('selected-sales-ack').checked};
$('selected-sales-preview').onclick=async()=>{invalidateSelectedSales();const sequence=selectedSalesSequence,dataset=$('dataset').value,batch_ids=[...$('received-batches').querySelectorAll('input:checked')].map(x=>x.value);selectedSalesBusy=true;$('selected-sales-preview').disabled=true;$('selected-sales-notice').textContent='Comprobando referencias, facturas y posibles duplicados…';try{const r=await api('/api/sales-history/preview',{method:'POST',headers:{'Content-Type':'application/json','X-EIOS-Token':token},body:JSON.stringify({dataset_id:dataset,context_fingerprint:state.documentary_context.fingerprint,batch_ids})});if(sequence!==selectedSalesSequence||dataset!==$('dataset').value)return;selectedSalesTicket=r.ticket;$('selected-sales-review').hidden=false;$('selected-sales-summary').textContent=r.files.join(' · ')+' · '+r.line_count+' líneas · '+r.error_count+' errores. Mostrando '+r.sample.length+' líneas.'+(r.replaces_previous_selection?' Sustituye la selección recibida anterior.':'');salesReceivedTable('selected-sales-rows',r.sample);$('selected-sales-notice').textContent=r.error_count?r.errors.map(e=>e.filename+' · fila '+e.row+' · '+(e.article_id||'SKU')+': '+e.message).join(' | '):'Revisa las líneas y confirma responsable, motivo y alcance antes de utilizarlas.';$('selected-sales-commit').disabled=!r.ticket||!$('selected-sales-ack').checked}catch(e){if(sequence===selectedSalesSequence)$('selected-sales-notice').textContent=e.message}finally{selectedSalesBusy=false;$('selected-sales-preview').disabled=false}};
async function changeSelectedSales(clear){if(selectedSalesBusy||(!clear&&!selectedSalesTicket))return;const dataset=$('dataset').value,sequence=selectedSalesSequence;selectedSalesBusy=true;$('selected-sales-commit').disabled=true;$('selected-sales-clear').disabled=true;try{const r=await api(clear?'/api/sales-history/clear':'/api/sales-history/commit',{method:'POST',headers:{'Content-Type':'application/json','X-EIOS-Token':token},body:JSON.stringify({dataset_id:dataset,context_fingerprint:state.documentary_context.fingerprint,ticket:selectedSalesTicket,actor:$('selected-sales-actor').value,reason:$('selected-sales-reason').value,acknowledge_references:$('selected-sales-ack').checked})});if(dataset!==$('dataset').value||sequence!==selectedSalesSequence)return;await refresh();$('selected-sales-notice').textContent=clear?'Selección retirada. Se recupera el historial documental original; las propuestas guardadas conservan sus referencias.':r.status==='UNCHANGED'?'Ese historial ya estaba seleccionado. No se ha duplicado.':'Historial recibido seleccionado. Consulta las líneas en Ventas y sus referencias en Propuestas de venta. Existencias y tesorería permanecen iguales.'}catch(e){if(dataset===$('dataset').value)$('selected-sales-notice').textContent=e.message}finally{selectedSalesBusy=false;$('selected-sales-commit').disabled=!selectedSalesTicket||!$('selected-sales-ack').checked;$('selected-sales-clear').disabled=!state.selected_sales_history||state.selected_sales_history.status==='CLEARED'}}
$('selected-sales-commit').onclick=()=>changeSelectedSales(false);$('selected-sales-clear').onclick=()=>changeSelectedSales(true);
'''
